insert into texts (level_code, genre, title, content, register, questions) select 'B1','verhaal','De fiets van Lotte',$c$Lotte woont in Utrecht en gaat elke dag met de fiets naar haar werk. Vorige week was haar fiets ineens weg. Ze had hem voor het station neergezet, maar toen ze terugkwam, lag er alleen nog een kapot slot. Eerst was ze boos. Daarna belde ze de politie, want ze wilde aangifte doen. De agent vertelde dat dit in Nederland vaak gebeurt. Gelukkig vond een collega een goede tweedehands fiets op internet. Lotte kocht hem voor honderdvijftig euro. Nu zet ze haar fiets altijd op slot, ook als ze maar vijf minuten weg is.$c$,'standard',$j${"glossary": [{"nl": "aangifte doen", "meaning_nl": "de politie vertellen dat er iets is gestolen"}, {"nl": "tweedehands", "meaning_nl": "al eerder gebruikt door iemand anders"}, {"nl": "op slot zetten", "meaning_nl": "met een slot vastmaken zodat niemand het kan pakken"}], "questions": [{"kind": "mcq", "tag": "lezen", "prompt": "Wat vond Lotte toen ze terugkwam bij het station?", "options": ["Haar fiets", "Een kapot slot", "Een briefje"], "answer": 1, "explanation": "Er lag alleen nog een kapot slot."}, {"kind": "mcq", "tag": "lezen", "prompt": "Wie hielp Lotte aan een nieuwe fiets?", "options": ["Een agent", "Haar buurman", "Een collega"], "answer": 2, "explanation": "Een collega vond een tweedehands fiets op internet."}, {"kind": "mcq", "tag": "lezen", "prompt": "Hoeveel kostte de nieuwe fiets?", "options": ["150 euro", "50 euro", "500 euro"], "answer": 0, "explanation": "Lotte kocht hem voor honderdvijftig euro."}]}$j$::jsonb where not exists (select 1 from texts where title='De fiets van Lotte');
insert into texts (level_code, genre, title, content, register, questions) select 'B1','e-mail','Nieuwe werktijden',$c$Beste collega's,

Vanaf 1 december veranderen onze werktijden. Het kantoor is dan open van acht tot zes uur. Je mag zelf kiezen wanneer je begint, zolang je acht uur per dag werkt. Op dinsdag en donderdag is iedereen op kantoor, want dan zijn er teamvergaderingen. Op de andere dagen mag je thuiswerken.

Wil je iets anders afspreken? Bespreek dat dan met je leidinggevende vóór 15 november.

Met vriendelijke groet,
Annemiek de Vries
Personeelszaken$c$,'formal',$j${"glossary": [{"nl": "leidinggevende", "meaning_nl": "de baas van je team"}, {"nl": "thuiswerken", "meaning_nl": "werken vanuit je eigen huis"}, {"nl": "zolang", "meaning_nl": "op voorwaarde dat"}], "questions": [{"kind": "mcq", "tag": "lezen", "prompt": "Wanneer gaan de nieuwe werktijden in?", "options": ["1 november", "1 december", "15 november"], "answer": 1, "explanation": "Vanaf 1 december veranderen de werktijden."}, {"kind": "mcq", "tag": "lezen", "prompt": "Op welke dagen is iedereen op kantoor?", "options": ["Dinsdag en donderdag", "Maandag en vrijdag", "Alleen op woensdag"], "answer": 0, "explanation": "Dan zijn er teamvergaderingen."}, {"kind": "mcq", "tag": "lezen", "prompt": "Voor wanneer moet je een andere afspraak bespreken?", "options": ["Voor 1 december", "Voor 1 januari", "Voor 15 november"], "answer": 2, "explanation": "Bespreek dat vóór 15 november met je leidinggevende."}]}$j$::jsonb where not exists (select 1 from texts where title='Nieuwe werktijden');
